INSERT INTO catalogs.items
  (id, operating_company_id, item_name, item_code, item_type, description,
   category_id, default_income_account_id, default_expense_account_id, notes)
SELECT gen_random_uuid(), '5c854333-6ea5-4faa-af31-67cb272fef80', s.item_name, s.item_code, s.item_type,
       NULLIF(s.description, ''),
       c.id,
       CASE WHEN s.posts_to IN ('revenue','income') THEN a.id END,
       CASE WHEN s.posts_to NOT IN ('revenue','income') THEN a.id END,
       NULLIF(s.mirrors_shortpay, '')
FROM src s
LEFT JOIN catalogs.qbo_categories c
       ON c.display_name = s.item_category AND c.operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80'
JOIN catalogs.accounts a
       ON a.account_number = s.account_number
      AND a.operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80' AND a.deactivated_at IS NULL
  -- IDEMPOTENCY WITHOUT ON CONFLICT. VERIFIED LIVE: catalogs.items has NO unique
  -- constraint on item_code — only items_pkey(id) and uq_items_company_id
  -- (operating_company_id, id). An ON CONFLICT (operating_company_id, item_code) would
  -- RAISE 'no unique or exclusion constraint matching the ON CONFLICT specification'.
WHERE NOT EXISTS (
  SELECT 1 FROM catalogs.items i
   WHERE i.operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80' AND i.item_code = s.item_code)
;

-- 3. RETIRE THE TEST ITEMS. Void-not-delete: they keep their history.
UPDATE catalogs.items SET deactivated_at = now()
 WHERE operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80' AND deactivated_at IS NULL
   AND (item_code IN ('CC2-BATTERY-20260807','P42-VFK-ITEM-0811',
                      'TESTCC3-MAINT-20260825','ZZ-GATEB-A','ZZ-GATEB-B')
    OR item_name ~* '^(TEST|ZZ-SAMPLE|CC2-|P42 )');

-- 4. PROOF, in the same transaction.
SELECT 'categories' AS what, count(*) AS n FROM catalogs.qbo_categories
 WHERE operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80'
UNION ALL SELECT 'items active', count(*) FROM catalogs.items
 WHERE operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80' AND deactivated_at IS NULL
UNION ALL SELECT 'items with NO account', count(*) FROM catalogs.items
 WHERE operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80' AND deactivated_at IS NULL
   AND default_income_account_id IS NULL AND default_expense_account_id IS NULL
UNION ALL SELECT 'items with NO category', count(*) FROM catalogs.items
 WHERE operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80' AND deactivated_at IS NULL
   AND category_id IS NULL
UNION ALL SELECT 'test items still active', count(*) FROM catalogs.items
 WHERE operating_company_id = '5c854333-6ea5-4faa-af31-67cb272fef80' AND deactivated_at IS NULL
   AND item_name ~* '^(TEST|ZZ-SAMPLE|CC2-|P42 )';

-- EXPECT: categories 19 · items active 137 · NO account 0 · NO category 2 (Hours, TONU are uncategorised in QBO) · test 0
COMMIT;
